// One-line description of each species trait, verified against the 2024 PHB (p.186-197). [en, da].
export const TRAIT_DESC={
  "Adrenaline Rush":["Bonus Action: Dash and gain temp HP = Prof. Bonus. Uses = Prof. Bonus per Short/Long Rest.","Bonus-handling: Dash og få midlertidige HP = Prof. Bonus. Antal brug = Prof. Bonus pr. Short/Long Rest."],
  "Brave":["Advantage on saving throws to avoid or end the Frightened condition.","Fordel på saving throws for at undgå eller afslutte Frightened."],
  "Breath Weapon":["Replace an attack with a 15-ft cone or 30-ft line; DEX save for half damage of your Draconic Ancestry's type (full on a fail), scales with level. Uses = Prof. Bonus per Long Rest.","Erstat et angreb med en 15 ft kegle eller 30 ft linje; DEX save for halv skade af typen fra din Draconic Ancestry (fuld skade ved fejl), skalerer med niveau. Antal brug = Prof. Bonus pr. Long Rest."],
  "Celestial Resistance":["Resistance to Necrotic and Radiant damage.","Modstand mod Necrotic- og Radiant-skade."],
  "Celestial Revelation":["Lvl 3: Bonus Action to transform (Heavenly Wings, Inner Radiance or Necrotic Shroud) for 1 minute, once per Long Rest. Once per turn while transformed, deal extra damage = Prof. Bonus (Necrotic for Necrotic Shroud, Radiant for the other two) on a hit.","Niv. 3: Bonus-handling til at transformere (Heavenly Wings, Inner Radiance eller Necrotic Shroud) i 1 minut, én gang pr. Long Rest. Én gang pr. tur mens du er transformeret: giv ekstra skade = Prof. Bonus (Necrotic for Necrotic Shroud, Radiant for de to andre) ved et træf."],
  "Damage Resistance":["Resistance to the damage type determined by your Draconic Ancestry.","Modstand mod skadetypen bestemt af din Draconic Ancestry."],
  "Darkvision 120 ft":["See in dim and dark light within 120 ft as if it were bright/dim light (no color in darkness).","Se i dæmpet og mørkt lys inden for 120 ft som var det lyst/dæmpet lys (ingen farver i mørke)."],
  "Darkvision 60 ft":["See in dim and dark light within 60 ft as if it were bright/dim light (no color in darkness).","Se i dæmpet og mørkt lys inden for 60 ft som var det lyst/dæmpet lys (ingen farver i mørke)."],
  "Draconic Ancestry":["Choose a dragon type; determines your Breath Weapon and Damage Resistance types.","Vælg en dragetype; bestemmer typen for dit Breath Weapon og Damage Resistance."],
  "Draconic Flight":["Lvl 5: Bonus Action to sprout spectral wings; Fly Speed = your Speed for 10 minutes, once per Long Rest.","Niv. 5: Bonus-handling til at få spektralvinger; Fly Speed = din Speed i 10 minutter, én gang pr. Long Rest."],
  "Dwarven Resilience":["Resistance to Poison damage. Advantage on saving throws to avoid or end the Poisoned condition.","Modstand mod Poison-skade. Fordel på saving throws for at undgå eller afslutte Poisoned."],
  "Dwarven Toughness":["Hit Point maximum increases by 1, and again by 1 every level.","Maks. HP stiger med 1, og igen med 1 hvert niveau."],
  "Elven Lineage":["Choose a lineage (Drow, High Elf or Wood Elf) for a bonus cantrip; learn a higher-level spell at levels 3 and 5.","Vælg en slægt (Drow, Højelver eller Skovelver) for en bonus-cantrip; lær en spell af højere niveau ved niv. 3 og 5."],
  "Fey Ancestry":["Advantage on saving throws to avoid or end the Charmed condition.","Fordel på saving throws for at undgå eller afslutte Charmed."],
  "Fiendish Legacy":["Choose a legacy (Abyssal, Chthonic or Infernal) for a damage resistance and cantrip; learn a higher-level spell at levels 3 and 5.","Vælg en arv (Abyssal, Chthonic eller Infernal) for skademodstand og cantrip; lær en spell af højere niveau ved niv. 3 og 5."],
  "Giant Ancestry":["Choose a giant-based boon, usable a number of times equal to Prof. Bonus per Long Rest.","Vælg en kæmpe-baseret gave, som kan bruges et antal gange svarende til Prof. Bonus pr. Long Rest."],
  "Gnomish Cunning":["Advantage on Intelligence, Wisdom and Charisma saving throws.","Fordel på Intelligence-, Wisdom- og Charisma-saving throws."],
  "Gnomish Lineage":["Choose Forest Gnome (Minor Illusion + Speak with Animals) or Rock Gnome (Mending + Prestidigitation, plus clockwork devices).","Vælg Skovgnom (Minor Illusion + Speak with Animals) eller Klippegnom (Mending + Prestidigitation, samt urværksapparater)."],
  "Halfling Nimbleness":["Move through the space of any creature that is a size larger than you.","Bevæg dig gennem feltet for et væsen, der er én størrelse større end dig."],
  "Healing Hands":["Magic action: touch a creature and roll a number of d4s equal to Prof. Bonus; it regains that many HP. Once per Long Rest.","Magisk handling: rør et væsen og kast et antal d4'ere svarende til Prof. Bonus; det genopretter så mange HP. Én gang pr. Long Rest."],
  "Keen Senses":["Proficiency in the Insight, Perception or Survival skill.","Proficiency i færdigheden Insight, Perception eller Survival."],
  "Large Form":["Lvl 5: Bonus Action to become Large for 10 minutes; Advantage on Strength checks, Speed +10 ft. Once per Long Rest.","Niv. 5: Bonus-handling til at blive Large i 10 minutter; fordel på Strength checks, Speed +10 ft. Én gang pr. Long Rest."],
  "Light Bearer":["You know the Light cantrip (Charisma).","Du kender cantrippen Light (Charisma)."],
  "Luck":["When you roll a 1 on the d20 of a D20 Test, you can reroll the die and must use the new roll.","Når du slår en 1'er på d20'eren i et D20 Test, kan du kaste om og skal bruge det nye resultat."],
  "Naturally Stealthy":["You can Hide even when obscured only by a creature at least one size larger than you.","Du kan bruge Hide selv når du kun er skjult af et væsen, der er mindst én størrelse større end dig."],
  "Otherworldly Presence":["You know the Thaumaturgy cantrip.","Du kender cantrippen Thaumaturgy."],
  "Powerful Build":["Advantage on saving throws to end the Grappled condition. Count as one size larger for carrying capacity.","Fordel på saving throws for at afslutte Grappled. Tæller som én størrelse større ift. bæreevne."],
  "Relentless Endurance":["When reduced to 0 HP but not killed outright, you can drop to 1 HP instead. Once per Long Rest.","Når du rammes ned til 0 HP uden at blive dræbt direkte, kan du i stedet falde til 1 HP. Én gang pr. Long Rest."],
  "Resourceful":["You gain Heroic Inspiration whenever you finish a Long Rest.","Du får Heroic Inspiration, hver gang du fuldfører en Long Rest."],
  "Skillful":["You gain proficiency in one skill of your choice.","Du får proficiency i én valgfri færdighed."],
  "Stonecunning":["Bonus Action: gain Tremorsense 60 ft for 10 minutes while on or touching stone. Uses = Prof. Bonus per Long Rest.","Bonus-handling: få Tremorsense 60 ft i 10 minutter mens du er på eller rører sten. Antal brug = Prof. Bonus pr. Long Rest."],
  "Trance":["You don't need to sleep. You can finish a Long Rest in 4 hours of trance instead.","Du behøver ikke sove. Du kan fuldføre en Long Rest på 4 timers trance i stedet."],
  "Versatile":["You gain an Origin feat of your choice.","Du får et valgfrit Origin-feat."],
};

